const x=$json;
if(!['health_check','reconcile','cleanup','freshness_check','security_check'].includes(x.operation))
 throw new Error('maintenance_invalid_operation');
if(!['all','commerce','database','kb','security','workflows'].includes(x.scope||'all'))
 throw new Error('maintenance_invalid_scope');
return [{json:{...x,scope:x.scope||'all',run_id:x.run_id||`maint_${Date.now()}`}}];

const x=$json;
const checks=[];
if(x.scope==='all'||x.scope==='commerce') checks.push({check:'woocommerce_gateway',operation:'health'});
if(x.scope==='all'||x.scope==='database') checks.push({check:'supabase_database',operation:'db_health'});
if(x.scope==='all'||x.scope==='kb') checks.push({check:'kb_freshness',operation:'freshness_check'});
if(x.scope==='all'||x.scope==='security') checks.push({check:'security_events',operation:'security_check'});
if(x.scope==='all'||x.scope==='workflows') checks.push({check:'workflow_failures',operation:'reconcile'});
return [{json:{...x,checks}}];

const x=$json;
// Integration placeholder: actual probes are wired to WF-20, Supabase and
// n8n execution APIs in the deployment environment.
const results=x.checks.map(c=>({
 check:c.check,status:'requires_environment_probe',
 operation:c.operation
}));
return [{json:{...x,results}}];

const x=$json;
const failed=x.results.filter(r=>r.status==='failed');
const pending=x.results.filter(r=>r.status==='requires_environment_probe');
let state=failed.length?'degraded':pending.length?'pending':'healthy';
return [{json:{...x,operational_state:state,failed_count:failed.length,pending_count:pending.length}}];
